@startuml

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + socialSecurityNumber : string
  + name : string
  + emailAddress : string
}

class ResearchAssistant extends Employee {
  + fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class AdministrativeStaff extends Employee {}

class Project {
  + name : string
  + startDate : date
  + endDate : date
}

class ProjectParticipation {
  + hours : int
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

Faculty "1" *-- "1..*" Institute : is made up of
Faculty "1" -- "1" Employee : is headed by
Employee "1" -- "*" ProjectParticipation : involved in
Project "1" -- "*" ProjectParticipation : has
ResearchAssistant "1..*" -- "1..*" Institute : is assigned to
Lecturer "1..*" -- "1..*" Course : teaches

@enduml

